\url{https://arxiv.org/abs/math-ph/0611006}.
\item[S4] Gottschalk--Thaler, triviality (catalogue-listed context; not independently consulted in this preparation).
\url{https://doi.org/10.1007/s00220-013-1796-9}.
\end{itemize}
